export const UK_REFERENCE={"id": "teng-2022-uk", "title": "Life tables of annual life expectancy and mortality for companion dogs in the United Kingdom", "authors": "Teng et al.", "published": 2022, "doi": "10.1038/s41598-022-10341-6", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC9050668/", "country": "GB", "population": "UK dogs under primary veterinary care; 2016 sampling frame; deaths January 2016–July 2020", "n": 30563, "metric": "cohort life table, pooled breeds", "e0": 11.23, "e0CI": [11.19, 11.27], "license": "CC BY 4.0", "retrieved": "2026-10-16", "annualQ": [0.017, 0.016, 0.016, 0.017, 0.02, 0.024, 0.033, 0.047, 0.069, 0.096, 0.134, 0.188, 0.244, 0.336, 0.417, 0.515, 0.593, 0.63, 0.683, 0.772, 1.0], "breedSummaries": [{"breed": "Jack Russell Terrier", "e0": 12.72, "ciText": "12.72 (12.53–12.90)", "n": 1620}, {"breed": "Yorkshire Terrier", "e0": 12.54, "ciText": "12.54 (12.30–12.77)", "n": 1042}, {"breed": "Border Collie", "e0": 12.1, "ciText": "12.10 (11.85–12.33)", "n": 942}, {"breed": "Springer Spaniel", "e0": 11.92, "ciText": "11.92 (11.69–12.13)", "n": 790}, {"breed": "Crossbred", "e0": 11.82, "ciText": "11.82 (11.72–11.92)", "n": 6511}, {"breed": "Labrador Retriever", "e0": 11.77, "ciText": "11.77 (11.67–11.89)", "n": 2500}, {"breed": "Staffordshire Bull Terrier", "e0": 11.33, "ciText": "11.33 (11.19–11.48)", "n": 2364}, {"breed": "Cocker Spaniel", "e0": 11.31, "ciText": "11.31 (11.13–11.53)", "n": 1073}, {"breed": "Shih-tzu", "e0": 11.05, "ciText": "11.05 (10.73–11.40)", "n": 638}, {"breed": "Cavalier King Charles Spaniel", "e0": 10.45, "ciText": "10.45 (10.26–10.62)", "n": 867}, {"breed": "German Shepherd Dog", "e0": 10.16, "ciText": "10.16 (10.00–10.370", "n": 1110}, {"breed": "Boxer", "e0": 10.04, "ciText": "10.04 (9.85–10.21)", "n": 836}, {"breed": "Beagle", "e0": 9.85, "ciText": "9.85 (9.17–10.24)", "n": 172}, {"breed": "Husky", "e0": 9.53, "ciText": "9.53 (8.71–9.88)", "n": 154}, {"breed": "Chihuahua", "e0": 7.91, "ciText": "7.91 (7.48–8.39)", "n": 458}, {"breed": "American Bulldog", "e0": 7.79, "ciText": "7.79 (7.16–8.33)", "n": 129}, {"breed": "Pug", "e0": 7.65, "ciText": "7.65 (6.99–8.20)", "n": 197}, {"breed": "English Bulldog", "e0": 7.39, "ciText": "7.39 (7.08–7.69)", "n": 478}, {"breed": "French Bulldog", "e0": 4.53, "ciText": "4.53 (4.14–5.01)", "n": 232}], "limitations": "No breed-specific annual hazards supplied here. UK pooled qx is a reference; transfer to other populations and age-within-year interpolation are model assumptions. No country-specific birth/environment frequencies are inferred."};
export function mortalityReference(s){return {source:UK_REFERENCE.id,scope:'영국 수의 진료 반려견 · 전체 품종',application:s.country.id==='GB'&&s.home==='family'?'연구 대상과 가까운 참고집단':'다른 국가·환경에 대한 기준 외삽',breedSpecific:false};}
export function dailyMortality(s){const age=Math.floor(Math.max(0,s.day-1)/365),q=UK_REFERENCE.annualQ[Math.min(age,19)];const baseline=1-Math.pow(1-q,1/365);const modifier=s.home==='family'?1:1.35;return Math.min(1,baseline*modifier);}
